import{_ as a,o,c as l,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Display-of-Variable-Labels.md","filePath":"manual-en/CTABLES-Display-of-Variable-Labels.md","lastUpdated":1785684581000}'),d={name:"manual-en/CTABLES-Display-of-Variable-Labels.md"};function t(r,e,p,i,c,n){return o(),l("div",null,[...e[0]||(e[0]=[s(`<h4 id="_15-7-8-display-of-variable-labels" tabindex="-1">15.7.8 Display of Variable Labels <a class="header-anchor" href="#_15-7-8-display-of-variable-labels" aria-label="Permalink to &quot;15.7.8 Display of Variable Labels&quot;">​</a></h4><pre><code>/VLABELS
    VARIABLES=_variables_
    DISPLAY={DEFAULT _|_ NAME _|_ LABEL _|_ BOTH _|_ NONE}
</code></pre><p>The <code>VLABELS</code> subcommand, which must precede the first <code>TABLE</code> subcommand, controls display of variable labels in all the output tables. <code>VLABELS</code> is optional. It may appear multiple times to adjust settings for different variables.</p><p><code>VARIABLES</code> and <code>DISPLAY</code> are required. The value of <code>DISPLAY</code> controls how variable labels are displayed for the variables listed on <code>VARIABLES</code>. The supported values are:</p><p><code>DEFAULT</code></p><p>Use the setting from <code>SET TVARS</code> (see <a href="./SET#SET-TVARS">SET TVARS</a>).</p><p><code>NAME</code></p><p>Show only a variable name.</p><p><code>LABEL</code></p><p>Show only a variable label.</p><p><code>BOTH</code></p><p>Show variable name and label.</p><p><code>NONE</code></p><p>Show nothing.</p>`,14)])])}const A=a(d,[["render",t]]);export{_ as __pageData,A as default};
